import { ROOM_W, ROOM_H, WALL, BOSS_FLOORS, MAX_FLOOR, themeForFloor } from './data.js';

export function makeRng(seed = Date.now()) {
  let a = (seed >>> 0) || 1;
  return function rng() {
    a += 0x6d2b79f5;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const DIRS = {
  n: { x: 0, y: -1, opposite: 's' },
  e: { x: 1, y: 0, opposite: 'w' },
  s: { x: 0, y: 1, opposite: 'n' },
  w: { x: -1, y: 0, opposite: 'e' }
};

const ROOM_NAMES = {
  ember: ['Hall of Cinders', 'The Rust Chapel', 'Ember Ward', 'Furnace Gallery', 'The Ashen Stair', 'Oathbreaker Vault'],
  verdant: ['Rootbound Gallery', 'The Green Reliquary', 'Thorn Choir', 'Moss Archive', 'The Blooming Cell', 'Matriarch’s Walk'],
  astral: ['Starfall Gallery', 'The Glass Orrery', 'Aether Observatory', 'The Ninth Window', 'Void Antechamber', 'The Silent Meridian'],
  crown: ['Throne of Rust', 'The Hollow Aisle', 'Crown’s Descent', 'The Last Balcony', 'Night’s Anvil', 'The Empty Court']
};

const ROOM_TYPES = {
  start: { label: 'Threshold', icon: '◈' },
  combat: { label: 'Sealed Hall', icon: '⚔' },
  treasure: { label: 'Hoard', icon: '✧' },
  shrine: { label: 'Shrine', icon: '✦' },
  exit: { label: 'Stair Gate', icon: '⇧' },
  boss: { label: 'Guardian', icon: '♛' }
};

function key(x, y) { return `${x},${y}`; }

function addRoom(rooms, x, y, parent, dir) {
  const k = key(x, y);
  if (rooms[k]) return rooms[k];
  const room = {
    key: k,
    x, y,
    doors: { n: null, e: null, s: null, w: null },
    parent: parent || null,
    type: 'combat',
    visited: false,
    cleared: false,
    spawned: false,
    enemies: [],
    obstacles: [],
    chestOpened: false,
    shrineUsed: false,
    depth: 0,
    name: ''
  };
  rooms[k] = room;
  if (parent && dir) {
    room.doors[DIRS[dir].opposite] = parent.key;
    parent.doors[dir] = room.key;
  }
  return room;
}

function connect(rooms, a, b, dir) {
  if (!a || !b) return;
  a.doors[dir] = b.key;
  b.doors[DIRS[dir].opposite] = a.key;
}

function walkableNeighbors(room, rooms) {
  const out = [];
  for (const [dir, d] of Object.entries(DIRS)) {
    const other = rooms[key(room.x + d.x, room.y + d.y)];
    if (other) out.push({ dir, room: other });
  }
  return out;
}

function bfs(rooms, start) {
  const dist = { [start.key]: 0 };
  const queue = [start];
  while (queue.length) {
    const room = queue.shift();
    for (const { room: next } of walkableNeighbors(room, rooms)) {
      if (dist[next.key] === undefined) {
        dist[next.key] = dist[room.key] + 1;
        queue.push(next);
      }
    }
  }
  return dist;
}

function placeObstacles(room, rand) {
  const count = rand() < 0.25 ? 0 : 1 + Math.floor(rand() * 3);
  const safe = [
    { x: ROOM_W / 2, y: ROOM_H / 2, r: 180 },
    { x: ROOM_W / 2, y: WALL + 130, r: 150 },
    { x: ROOM_W / 2, y: ROOM_H - WALL - 130, r: 150 },
    { x: WALL + 130, y: ROOM_H / 2, r: 150 },
    { x: ROOM_W - WALL - 130, y: ROOM_H / 2, r: 150 }
  ];
  let attempts = 0;
  while (room.obstacles.length < count && attempts < 80) {
    attempts++;
    const x = WALL + 100 + rand() * (ROOM_W - WALL * 2 - 200);
    const y = WALL + 100 + rand() * (ROOM_H - WALL * 2 - 200);
    if (safe.some(s => Math.hypot(x - s.x, y - s.y) < s.r)) continue;
    if (room.obstacles.some(o => Math.hypot(x - o.x, y - o.y) < 150)) continue;
    room.obstacles.push({
      x, y,
      r: 22 + rand() * 12,
      kind: rand() < 0.45 ? 'pillar' : rand() < 0.6 ? 'statue' : 'crystal',
      seed: rand()
    });
  }
}

export function generateFloor(floor, rand = Math.random) {
  const theme = themeForFloor(floor);
  const rooms = {};
  const start = addRoom(rooms, 3, 3, null, null);
  const targetCount = BOSS_FLOORS.includes(floor)
    ? (floor === 12 ? 6 : 5)
    : 7 + Math.floor(rand() * 3);
  const frontier = [start];
  let guard = 0;
  while (Object.keys(rooms).length < targetCount && guard++ < 400) {
    const base = frontier[Math.floor(rand() * frontier.length)];
    const options = Object.entries(DIRS)
      .filter(([, d]) => {
        const nx = base.x + d.x, ny = base.y + d.y;
        return nx >= 0 && nx < 7 && ny >= 0 && ny < 7 && !rooms[key(nx, ny)];
      });
    if (!options.length) { frontier.splice(frontier.indexOf(base), 1); if (!frontier.length) break; continue; }
    const [dir, d] = options[Math.floor(rand() * options.length)];
    const next = addRoom(rooms, base.x + d.x, base.y + d.y, base, dir);
    frontier.push(next);
    // Occasional side connections create loops and make the map feel less like a corridor.
    if (rand() < 0.18) {
      const side = Object.entries(DIRS)[Math.floor(rand() * 4)];
      const other = rooms[key(next.x + side[1].x, next.y + side[1].y)];
      if (other && other !== base && !next.doors[side[0]]) connect(rooms, next, other, side[0]);
    }
  }

  const dist = bfs(rooms, start);
  let farthest = start;
  for (const room of Object.values(rooms)) {
    room.depth = dist[room.key] || 0;
    if (room.depth > farthest.depth) farthest = room;
  }

  if (BOSS_FLOORS.includes(floor)) {
    farthest.type = 'boss';
    const rest = Object.values(rooms).filter(r => r !== start && r !== farthest);
    const pool = rest.sort(() => rand() - 0.5);
    if (pool[0]) pool[0].type = 'shrine';
    if (pool[1]) pool[1].type = 'treasure';
  } else {
    farthest.type = 'exit';
    const rest = Object.values(rooms)
      .filter(r => r !== start && r !== farthest)
      .sort((a, b) => b.depth - a.depth);
    if (rest[0] && rand() < 0.85) rest[0].type = 'treasure';
    const shrineCandidates = rest.filter(r => r.type === 'combat');
    if (shrineCandidates.length) {
      shrineCandidates[Math.floor(rand() * shrineCandidates.length)].type = 'shrine';
    }
  }

  const names = ROOM_NAMES[theme.id];
  for (const room of Object.values(rooms)) {
    if (room.type === 'start') room.name = 'The Threshold';
    else if (room.type === 'boss') room.name = floor === 12 ? 'The Empty Court' : floor === 8 ? 'The Blooming Cell' : 'The Ashen Stair';
    else if (room.type === 'exit') room.name = 'The Stair Gate';
    else if (room.type === 'shrine') room.name = 'Aether Shrine';
    else if (room.type === 'treasure') room.name = 'Sealed Hoard';
    else room.name = names[Math.floor(rand() * names.length)];
    placeObstacles(room, rand);
  }

  const roomsList = Object.values(rooms);
  return {
    floor,
    theme,
    rooms,
    list: roomsList,
    startKey: start.key,
    exitKey: farthest.type === 'exit' ? farthest.key : null,
    bossKey: farthest.type === 'boss' ? farthest.key : null,
    maxDepth: farthest.depth,
    seed: Math.floor(rand() * 1e9),
    required: roomsList.filter(r => r.type === 'combat' || r.type === 'boss').length
  };
}

export function roomTypeInfo(type) {
  return ROOM_TYPES[type] || ROOM_TYPES.combat;
}

export function doorPoint(room, dir) {
  switch (dir) {
    case 'n': return { x: ROOM_W / 2, y: WALL / 2 };
    case 's': return { x: ROOM_W / 2, y: ROOM_H - WALL / 2 };
    case 'w': return { x: WALL / 2, y: ROOM_H / 2 };
    case 'e': return { x: ROOM_W - WALL / 2, y: ROOM_H / 2 };
    default: return { x: ROOM_W / 2, y: ROOM_H / 2 };
  }
}

export function doorAperture(room, dir) {
  const c = doorPoint(room, dir);
  const half = 72;
  if (dir === 'n' || dir === 's') return { x: c.x - half, y: c.y - 8, w: half * 2, h: 16 };
  return { x: c.x - 8, y: c.y - half, w: 16, h: half * 2 };
}

export function roomCenter(room) {
  return { x: ROOM_W / 2, y: ROOM_H / 2 };
}

import {
  SAVE_KEY, RANKS, MAX_FLOOR, CONTRACT_TEMPLATES, WEAPONS, ARMORS, CHARMS
} from './data.js';

export function rankIndexForXp(xp = 0) {
  let index = 0;
  for (let i = 0; i < RANKS.length; i++) if (xp >= RANKS[i].xp) index = i;
  return index;
}

export function rankForXp(xp = 0) {
  return RANKS[rankIndexForXp(xp)];
}

export function nextRank(xp = 0) {
  return RANKS.find(r => r.xp > xp) || null;
}

export function uid() {
  return Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-4);
}

export function contractProgress(save, contract) {
  if (!contract) return { value: 0, target: 1, complete: false, label: '' };
  const current = save.stats[contract.stat] || 0;
  const value = contract.absolute ? Math.min(current, contract.target) : Math.max(0, current - contract.start);
  return {
    value,
    target: contract.target,
    complete: value >= contract.target,
    label: `${Math.min(value, contract.target)} / ${contract.target}`
  };
}

export function generateContract(save, rand = Math.random, avoidIds = []) {
  const rank = rankIndexForXp(save.licenseXp);
  let pool = CONTRACT_TEMPLATES.filter(t => !avoidIds.includes(t.id));
  if ((save.stats.bestFloor || 0) >= MAX_FLOOR) pool = pool.filter(t => t.id !== 'depth');
  if (!pool.length) pool = CONTRACT_TEMPLATES.filter(t => t.id !== 'depth');
  const template = pool[Math.floor(rand() * pool.length)];
  let target;
  if (template.absolute) {
    target = Math.max(2, Math.min(MAX_FLOOR, Math.max(save.checkpointFloor || 1, save.stats.bestFloor + 1)));
  } else {
    target = Math.max(1, Math.round(template.min + rank * template.scale + rand() * (template.max - template.min) * 0.8));
  }
  const rewardScale = 0.85 + rank * 0.22;
  const rewardShards = Math.round((22 + target * 3.5) * template.reward * rewardScale);
  const rewardXp = Math.round((35 + target * 5) * template.reward * rewardScale);
  return {
    id: uid(),
    templateId: template.id,
    title: template.title,
    stat: template.stat,
    unit: template.unit,
    absolute: Boolean(template.absolute),
    start: template.absolute ? 0 : (save.stats[template.stat] || 0),
    target,
    rewardShards,
    rewardXp,
    createdAt: Date.now()
  };
}

export function refillContracts(save, rand = Math.random) {
  const active = new Set((save.contracts || []).map(c => c.templateId));
  while ((save.contracts || []).length < 3) {
    const c = generateContract(save, rand, [...active]);
    save.contracts.push(c);
    active.add(c.templateId);
  }
  return save.contracts;
}

export function defaultSave(rand = Math.random) {
  const save = {
    version: 1,
    createdAt: Date.now(),
    updatedAt: Date.now(),
    licenseXp: 0,
    shards: 0,
    checkpointFloor: 1,
    hunter: { name: 'Lyra Vane', id: 'HV-0713' },
    stats: {
      kills: 0,
      killsByType: {},
      floors: 0,
      rooms: 0,
      bosses: 0,
      shardsEarned: 0,
      boons: 0,
      bestFloor: 0,
      runs: 0,
      deaths: 0,
      wins: 0
    },
    meta: { vitality: 0, might: 0, agility: 0, aether: 0, fortune: 0 },
    equipment: {
      weapon: 'saber',
      armor: 'coat',
      charm: null,
      levels: {
        saber: 1, daggers: 1, greatsword: 1,
        coat: 1, mail: 1, vestment: 1
      }
    },
    unlocked: {
      weapons: ['saber'],
      armors: ['coat'],
      charms: []
    },
    contracts: [],
    settings: { sound: true, music: true, shake: true, hints: true },
    lastRun: null
  };
  refillContracts(save, rand);
  return save;
}

function mergeDefaults(target, defaults) {
  for (const [key, value] of Object.entries(defaults)) {
    if (target[key] === undefined) target[key] = value;
    else if (value && typeof value === 'object' && !Array.isArray(value)) {
      if (typeof target[key] !== 'object' || target[key] === null) target[key] = value;
      else mergeDefaults(target[key], value);
    }
  }
  return target;
}

export function normalizeSave(raw) {
  const save = mergeDefaults(raw || {}, defaultSave(Math.random));
  if (!Array.isArray(save.contracts)) save.contracts = [];
  save.contracts = save.contracts.filter(c => c && c.templateId && c.stat);
  if (save.contracts.length < 3) refillContracts(save);
  // Repair any save that references equipment the player does not own.
  if (!WEAPONS[save.equipment.weapon] || !save.unlocked.weapons.includes(save.equipment.weapon)) save.equipment.weapon = 'saber';
  if (!ARMORS[save.equipment.armor] || !save.unlocked.armors.includes(save.equipment.armor)) save.equipment.armor = 'coat';
  if (save.equipment.charm && (!CHARMS[save.equipment.charm] || !save.unlocked.charms.includes(save.equipment.charm))) save.equipment.charm = null;
  return save;
}

export function loadSave() {
  try {
    if (typeof localStorage === 'undefined') return defaultSave();
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return defaultSave();
    return normalizeSave(JSON.parse(raw));
  } catch (error) {
    console.warn('Could not load save, starting fresh.', error);
    return defaultSave();
  }
}

export function saveGame(save) {
  save.updatedAt = Date.now();
  try {
    if (typeof localStorage !== 'undefined') localStorage.setItem(SAVE_KEY, JSON.stringify(save));
  } catch (error) {
    console.warn('Could not persist save.', error);
  }
  return save;
}

export function resetSave() {
  try { if (typeof localStorage !== 'undefined') localStorage.removeItem(SAVE_KEY); } catch {}
  return defaultSave();
}

export function addShards(save, amount) {
  const value = Math.max(0, Math.round(amount));
  save.shards += value;
  save.stats.shardsEarned = (save.stats.shardsEarned || 0) + value;
  return value;
}

export function addLicenseXp(save, amount) {
  const before = rankIndexForXp(save.licenseXp);
  save.licenseXp = Math.max(0, Math.round(save.licenseXp + amount));
  const after = rankIndexForXp(save.licenseXp);
  return {
    amount,
    rankUp: after > before,
    from: RANKS[before],
    to: RANKS[after]
  };
}

export function bumpStat(save, stat, amount = 1) {
  save.stats[stat] = (save.stats[stat] || 0) + amount;
}

export function bumpKill(save, type) {
  bumpStat(save, 'kills', 1);
  if (!save.stats.killsByType) save.stats.killsByType = {};
  save.stats.killsByType[type] = (save.stats.killsByType[type] || 0) + 1;
}

export function claimContract(save, id) {
  const idx = save.contracts.findIndex(c => c.id === id);
  if (idx < 0) return { ok: false, reason: 'Contract not found.' };
  const contract = save.contracts[idx];
  if (!contractProgress(save, contract).complete) return { ok: false, reason: 'Contract incomplete.' };
  const shards = addShards(save, contract.rewardShards);
  const xp = addLicenseXp(save, contract.rewardXp);
  save.contracts.splice(idx, 1);
  const active = new Set(save.contracts.map(c => c.templateId));
  save.contracts.push(generateContract(save, Math.random, [...active]));
  saveGame(save);
  return { ok: true, shards, xp: xp.amount, rankUp: xp };
}

export function equipItem(save, slot, id) {
  if (slot === 'weapon' && !save.unlocked.weapons.includes(id)) return false;
  if (slot === 'armor' && !save.unlocked.armors.includes(id)) return false;
  if (slot === 'charm' && !save.unlocked.charms.includes(id)) return false;
  save.equipment[slot] = id;
  saveGame(save);
  return true;
}

export function unlockItem(save, slot, id) {
  const table = slot === 'weapon' ? WEAPONS : slot === 'armor' ? ARMORS : CHARMS;
  const item = table[id];
  if (!item) return { ok: false, reason: 'Unknown item.' };
  const list = slot === 'weapon' ? save.unlocked.weapons : slot === 'armor' ? save.unlocked.armors : save.unlocked.charms;
  if (list.includes(id)) return { ok: false, reason: 'Already unlocked.' };
  if (save.shards < item.unlock) return { ok: false, reason: 'Not enough shards.' };
  save.shards -= item.unlock;
  list.push(id);
  saveGame(save);
  return { ok: true };
}

export function upgradeEquipment(save, id) {
  const levels = save.equipment.levels;
  const level = levels[id] || 1;
  if (level >= 5) return { ok: false, reason: 'Already at maximum.' };
  const cost = Math.round(45 * level * level);
  if (save.shards < cost) return { ok: false, reason: 'Not enough shards.' };
  save.shards -= cost;
  levels[id] = level + 1;
  saveGame(save);
  return { ok: true, cost, level: level + 1 };
}

export function upgradeMeta(save, id) {
  const meta = save.meta[id];
  const def = { vitality: { max: 5, cost: 50, step: 42 }, might: { max: 5, cost: 65, step: 50 }, agility: { max: 4, cost: 45, step: 40 }, aether: { max: 4, cost: 55, step: 45 }, fortune: { max: 3, cost: 75, step: 55 } }[id];
  if (!def) return { ok: false, reason: 'Unknown upgrade.' };
  const current = meta || 0;
  if (current >= def.max) return { ok: false, reason: 'Already at maximum.' };
  const cost = def.cost + current * def.step;
  if (save.shards < cost) return { ok: false, reason: 'Not enough shards.' };
  save.shards -= cost;
  save.meta[id] = current + 1;
  saveGame(save);
  return { ok: true, cost, level: current + 1 };
}

export function moveCheckpoint(save, floor) {
  if (floor > save.checkpointFloor && floor <= MAX_FLOOR) {
    save.checkpointFloor = floor;
    saveGame(save);
    return true;
  }
  return false;
}

export function formatNumber(value) {
  return Math.round(value).toLocaleString('en-US');
}

// Tiny synthesized audio engine. No external assets, no network requests.
export class AudioEngine {
  constructor(settings = {}) {
    this.settings = settings;
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.noiseBuffer = null;
    this.musicTimer = null;
    this.musicStep = 0;
    this.ready = false;
  }

  init() {
    if (this.ready) return;
    const Ctor = window.AudioContext || window.webkitAudioContext;
    if (!Ctor) return;
    try {
      this.ctx = new Ctor();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.settings.sound === false ? 0 : 0.9;
      this.master.connect(this.ctx.destination);
      this.sfxGain = this.ctx.createGain();
      this.sfxGain.gain.value = 0.62;
      this.sfxGain.connect(this.master);
      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = this.settings.music === false ? 0 : 0.2;
      this.musicGain.connect(this.master);
      const len = this.ctx.sampleRate * 1.4;
      this.noiseBuffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const data = this.noiseBuffer.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
      this.ready = true;
      this.startMusic();
    } catch (error) {
      console.warn('Audio unavailable', error);
    }
  }

  resume() {
    this.init();
    if (this.ctx?.state === 'suspended') this.ctx.resume().catch(() => {});
  }

  syncSettings() {
    if (!this.ready) return;
    this.master.gain.setTargetAtTime(this.settings.sound === false ? 0 : 0.9, this.ctx.currentTime, 0.04);
    this.musicGain.gain.setTargetAtTime(this.settings.music === false ? 0 : 0.2, this.ctx.currentTime, 0.2);
  }

  tone({ freq = 220, to = freq, dur = 0.15, type = 'sine', gain = 0.2, delay = 0, filter = null }) {
    if (!this.ready || this.settings.sound === false) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (to !== freq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    if (filter) {
      const f = this.ctx.createBiquadFilter();
      f.type = filter.type || 'lowpass';
      f.frequency.setValueAtTime(filter.freq || 1200, t);
      if (filter.to) f.frequency.exponentialRampToValueAtTime(filter.to, t + dur);
      osc.connect(f);
      f.connect(g);
    } else osc.connect(g);
    g.connect(this.sfxGain);
    osc.start(t);
    osc.stop(t + dur + 0.03);
  }

  noise({ dur = 0.18, gain = 0.16, type = 'highpass', freq = 900, to = null, delay = 0 }) {
    if (!this.ready || this.settings.sound === false) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, t);
    if (to) f.frequency.exponentialRampToValueAtTime(to, t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f);
    f.connect(g);
    g.connect(this.sfxGain);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  play(name) {
    if (!this.ready || this.settings.sound === false) return;
    switch (name) {
      case 'ui':
        this.tone({ freq: 620, to: 820, dur: 0.055, type: 'triangle', gain: 0.07 });
        break;
      case 'hover':
        this.tone({ freq: 480, to: 500, dur: 0.03, type: 'sine', gain: 0.026 });
        break;
      case 'slash':
        this.noise({ dur: 0.16, gain: 0.13, freq: 1800, to: 600 });
        this.tone({ freq: 320, to: 150, dur: 0.1, type: 'sawtooth', gain: 0.035 });
        break;
      case 'hit':
        this.noise({ dur: 0.1, gain: 0.17, freq: 900, to: 200 });
        this.tone({ freq: 130, to: 55, dur: 0.16, type: 'square', gain: 0.09 });
        break;
      case 'crit':
        this.tone({ freq: 1050, to: 1650, dur: 0.1, type: 'triangle', gain: 0.12 });
        this.tone({ freq: 135, to: 55, dur: 0.2, type: 'square', gain: 0.1, delay: 0.01 });
        break;
      case 'hurt':
        this.tone({ freq: 190, to: 70, dur: 0.25, type: 'sawtooth', gain: 0.13 });
        this.noise({ dur: 0.18, gain: 0.08, freq: 500, to: 120 });
        break;
      case 'dash':
        this.noise({ dur: 0.22, gain: 0.1, freq: 300, to: 2400, type: 'bandpass' });
        this.tone({ freq: 260, to: 600, dur: 0.15, type: 'sine', gain: 0.035 });
        break;
      case 'lance':
        this.tone({ freq: 520, to: 1500, dur: 0.22, type: 'triangle', gain: 0.12 });
        this.noise({ dur: 0.15, gain: 0.07, freq: 2600, to: 900 });
        break;
      case 'nova':
        this.tone({ freq: 150, to: 60, dur: 0.45, type: 'sawtooth', gain: 0.12 });
        this.tone({ freq: 800, to: 220, dur: 0.4, type: 'triangle', gain: 0.08 });
        this.noise({ dur: 0.5, gain: 0.1, freq: 300, to: 2600, type: 'bandpass' });
        break;
      case 'pickup':
        this.tone({ freq: 800, to: 1250, dur: 0.09, type: 'sine', gain: 0.1 });
        this.tone({ freq: 1250, to: 1600, dur: 0.1, type: 'sine', gain: 0.07, delay: 0.06 });
        break;
      case 'shard':
        this.tone({ freq: 1200, to: 1900, dur: 0.055, type: 'triangle', gain: 0.035 });
        break;
      case 'chest':
        this.tone({ freq: 230, to: 300, dur: 0.25, type: 'triangle', gain: 0.1 });
        this.tone({ freq: 700, to: 1100, dur: 0.3, type: 'sine', gain: 0.08, delay: 0.16 });
        break;
      case 'shrine':
        this.tone({ freq: 330, to: 660, dur: 0.5, type: 'sine', gain: 0.1 });
        this.tone({ freq: 495, to: 990, dur: 0.5, type: 'sine', gain: 0.06, delay: 0.08 });
        break;
      case 'portal':
        this.tone({ freq: 180, to: 900, dur: 0.7, type: 'sine', gain: 0.1 });
        this.tone({ freq: 300, to: 1400, dur: 0.7, type: 'triangle', gain: 0.05, delay: 0.1 });
        break;
      case 'boss':
        this.tone({ freq: 75, to: 42, dur: 1.1, type: 'sawtooth', gain: 0.15 });
        this.tone({ freq: 140, to: 80, dur: 0.9, type: 'square', gain: 0.06 });
        this.noise({ dur: 0.8, gain: 0.08, freq: 180, to: 80 });
        break;
      case 'death':
        this.tone({ freq: 300, to: 55, dur: 1.2, type: 'sawtooth', gain: 0.12 });
        this.tone({ freq: 150, to: 30, dur: 1.4, type: 'sine', gain: 0.1 });
        break;
      case 'rank':
        [440, 554, 659, 880].forEach((f, i) => this.tone({ freq: f, dur: 0.32, type: 'triangle', gain: 0.08, delay: i * 0.09 }));
        break;
      case 'boon':
        [330, 440, 660].forEach((f, i) => this.tone({ freq: f, dur: 0.5, type: 'sine', gain: 0.08, delay: i * 0.08 }));
        break;
      case 'victory':
        [261, 329, 392, 523, 659].forEach((f, i) => this.tone({ freq: f, dur: 0.7, type: 'triangle', gain: 0.09, delay: i * 0.13 }));
        break;
      case 'error':
        this.tone({ freq: 140, to: 110, dur: 0.16, type: 'square', gain: 0.08 });
        break;
      default:
        break;
    }
  }

  startMusic() {
    if (!this.ready || this.musicTimer) return;
    const chords = [
      [110, 164.81, 220, 293.66],
      [98, 146.83, 196, 261.63],
      [87.31, 130.81, 174.61, 246.94],
      [82.41, 123.47, 164.81, 220]
    ];
    const playChord = () => {
      if (!this.ready || this.settings.music === false) return;
      const t = this.ctx.currentTime;
      const chord = chords[this.musicStep % chords.length];
      const gain = this.musicGain;
      chord.forEach((freq, index) => {
        const osc = this.ctx.createOscillator();
        const g = this.ctx.createGain();
        const filter = this.ctx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.value = 560 + index * 160;
        osc.type = index === 0 ? 'triangle' : 'sine';
        osc.frequency.value = freq;
        osc.detune.value = (Math.random() - 0.5) * 7;
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(0.045 / (index + 1), t + 1.6);
        g.gain.exponentialRampToValueAtTime(0.0001, t + 7.5);
        osc.connect(filter);
        filter.connect(g);
        g.connect(gain);
        osc.start(t);
        osc.stop(t + 7.7);
      });
      // A sparse, distant bell gives the tower a sense of scale.
      if (this.musicStep % 2 === 0) {
        const bell = this.ctx.createOscillator();
        const bg = this.ctx.createGain();
        bell.type = 'sine';
        bell.frequency.value = chord[2] * 4;
        bg.gain.setValueAtTime(0.0001, t + 1.1);
        bg.gain.exponentialRampToValueAtTime(0.016, t + 1.2);
        bg.gain.exponentialRampToValueAtTime(0.0001, t + 5.5);
        bell.connect(bg);
        bg.connect(gain);
        bell.start(t + 1.1);
        bell.stop(t + 5.6);
      }
      this.musicStep++;
    };
    playChord();
    this.musicTimer = setInterval(playChord, 7200);
  }
}

:root {
  --ink: #07060b;
  --ink-2: #0d0a13;
  --panel: rgba(16, 12, 23, 0.92);
  --panel-solid: #100c17;
  --panel-2: rgba(24, 18, 33, 0.92);
  --parchment: #f4e8d1;
  --parchment-dim: #cec0aa;
  --muted: #9b91a8;
  --faint: #6e6579;
  --gold: #e4b76c;
  --gold-bright: #ffdb99;
  --gold-dark: #8a6333;
  --rose: #f17d8d;
  --teal: #78e3c7;
  --violet: #a996ff;
  --danger: #ef6a72;
  --line: rgba(228, 183, 108, 0.22);
  --line-soft: rgba(228, 183, 108, 0.11);
  --serif: "Palatino Linotype", "Book Antiqua", Palatino, Georgia, "Times New Roman", serif;
  --sans: "Trebuchet MS", "Segoe UI", Tahoma, sans-serif;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--parchment);
  font-family: var(--sans);
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body { touch-action: none; }

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
}

button:focus-visible {
  outline: 1px solid var(--gold-bright);
  outline-offset: 3px;
}

.hidden { display: none !important; }

#game-root { position: fixed; inset: 0; overflow: hidden; background: #06050a; }

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

#world-fx { position: absolute; inset: 0; pointer-events: none; z-index: 2; }

#vignette {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 50% 48%, transparent 42%, rgba(4, 3, 8, 0.36) 78%, rgba(3, 2, 6, 0.82) 100%),
    linear-gradient(to bottom, rgba(4, 3, 9, 0.32), transparent 18%, transparent 75%, rgba(4, 3, 9, 0.42));
  mix-blend-mode: multiply;
}

#damage-flash {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(198, 24, 48, 0.7));
  opacity: 0;
  transition: opacity 180ms ease-out;
}

/* ============================== LOADING ============================== */
#loading-screen {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: radial-gradient(circle at 50% 45%, #17101f, #07060b 62%);
  transition: opacity 500ms ease, visibility 500ms ease;
}
#loading-screen.done { opacity: 0; visibility: hidden; }
#loading-screen p {
  margin: 0;
  font-size: 10px;
  letter-spacing: 0.42em;
  color: var(--gold);
  text-transform: uppercase;
}
.loading-mark {
  width: 64px;
  height: 64px;
  border: 1px solid var(--line);
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 24px;
  color: var(--gold-bright);
  animation: pulseGlow 2.2s ease-in-out infinite;
  box-shadow: 0 0 50px rgba(228, 183, 108, 0.14), inset 0 0 24px rgba(228, 183, 108, 0.08);
}

@keyframes pulseGlow {
  0%, 100% { box-shadow: 0 0 24px rgba(228, 183, 108, 0.1), inset 0 0 20px rgba(228, 183, 108, 0.05); transform: scale(1); }
  50% { box-shadow: 0 0 64px rgba(228, 183, 108, 0.25), inset 0 0 30px rgba(228, 183, 108, 0.12); transform: scale(1.04); }
}

/* ============================== SCREENS ============================== */
.screen {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: screenIn 520ms cubic-bezier(.2,.8,.2,1) both;
}

@keyframes screenIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: none; }
}

.eyebrow {
  margin: 0;
  color: var(--gold);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.38em;
  text-transform: uppercase;
}

/* ============================== TITLE ============================== */
.title-screen {
  padding: calc(26px + var(--safe-top)) clamp(22px, 5vw, 78px) calc(18px + var(--safe-bottom));
  background:
    radial-gradient(ellipse at 18% 38%, rgba(61, 31, 58, 0.25), transparent 52%),
    linear-gradient(90deg, rgba(5, 4, 9, 0.92) 0%, rgba(5, 4, 9, 0.56) 42%, rgba(5, 4, 9, 0.08) 72%, rgba(5, 4, 9, 0.38) 100%),
    linear-gradient(to top, rgba(5, 4, 9, 0.92), transparent 36%);
  justify-content: space-between;
}

.title-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(112deg, transparent 0 96px, rgba(228, 183, 108, 0.018) 96px 97px, transparent 97px 190px),
    radial-gradient(circle at 76% 20%, rgba(228, 183, 108, 0.07), transparent 36%);
  pointer-events: none;
}

.title-grain {
  position: absolute;
  inset: 0;
  opacity: 0.18;
  pointer-events: none;
  background-image:
    radial-gradient(rgba(255,255,255,0.16) 0.6px, transparent 0.7px),
    radial-gradient(rgba(255,255,255,0.1) 0.5px, transparent 0.6px);
  background-size: 5px 5px, 9px 9px;
  background-position: 0 0, 3px 4px;
  mix-blend-mode: soft-light;
}

.title-topbar, .title-footer {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.brand-mark {
  font-size: 9px;
  letter-spacing: 0.3em;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 10px;
}
.brand-mark span { color: var(--gold); font-size: 15px; }

.title-tools { display: flex; align-items: center; gap: 10px; }

.icon-button {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgba(12, 9, 18, 0.66);
  color: var(--gold);
  font-size: 14px;
  transition: border-color 180ms, background 180ms, transform 180ms;
  backdrop-filter: blur(10px);
}
.icon-button:hover { border-color: var(--gold); background: rgba(45, 32, 25, 0.72); transform: translateY(-1px); }

.title-layout {
  position: relative;
  z-index: 2;
  width: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1.42fr) minmax(280px, 0.58fr);
  align-items: end;
  gap: clamp(28px, 5vw, 90px);
  padding: clamp(20px, 6vh, 84px) 0 clamp(26px, 6vh, 74px);
  flex: 1;
}

.title-copy { max-width: 860px; align-self: center; }

.game-title {
  margin: 14px 0 0;
  font-family: var(--serif);
  font-size: clamp(3.9rem, 8.7vw, 9.4rem);
  font-weight: 400;
  line-height: 0.82;
  letter-spacing: 0.045em;
  color: var(--parchment);
  text-shadow: 0 0 50px rgba(228, 183, 108, 0.16), 0 10px 34px rgba(0, 0, 0, 0.7);
  white-space: nowrap;
}
.game-title span {
  color: transparent;
  background: linear-gradient(180deg, #ffdfa3 5%, #dba75a 54%, #9f6a32 100%);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 28px rgba(228, 183, 108, 0.2));
}

.title-rule {
  display: flex;
  align-items: center;
  gap: 15px;
  width: min(640px, 100%);
  margin: 24px 0 20px;
  color: var(--gold);
}
.title-rule span { height: 1px; flex: 1; background: linear-gradient(90deg, transparent, var(--gold-dark), transparent); }
.title-rule em {
  font-family: var(--serif);
  font-size: clamp(12px, 1.2vw, 16px);
  font-style: normal;
  letter-spacing: 0.52em;
  white-space: nowrap;
  padding-left: 0.5em;
}

.title-blurb {
  margin: 0 0 30px;
  max-width: 610px;
  font-family: var(--serif);
  font-size: clamp(15px, 1.28vw, 19px);
  line-height: 1.72;
  color: #cfc2b1;
}

.title-actions { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }

.primary-button, .secondary-button {
  position: relative;
  min-height: 52px;
  padding: 0 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  transition: transform 180ms, box-shadow 180ms, background 180ms, border-color 180ms;
}

.primary-button {
  color: #171006;
  background: linear-gradient(135deg, #ffe4ae, #d7a054 58%, #be7e39);
  border: 1px solid #ffe1a6;
  box-shadow: 0 7px 26px rgba(201, 143, 69, 0.24), inset 0 1px rgba(255, 255, 255, 0.44);
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
}
.primary-button:hover { transform: translateY(-2px); box-shadow: 0 12px 40px rgba(236, 178, 92, 0.34), inset 0 1px rgba(255,255,255,0.55); }
.primary-button:active { transform: translateY(0); }

.secondary-button {
  color: var(--parchment);
  border: 1px solid rgba(228, 183, 108, 0.32);
  background: rgba(10, 8, 15, 0.46);
  backdrop-filter: blur(8px);
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
}
.secondary-button:hover { border-color: var(--gold); background: rgba(61, 43, 28, 0.5); transform: translateY(-2px); }

.continue-line {
  margin: 15px 0 0;
  color: var(--faint);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.control-hints {
  display: flex;
  gap: 18px 24px;
  flex-wrap: wrap;
  margin-top: 34px;
  padding-top: 18px;
  border-top: 1px solid var(--line-soft);
  color: var(--faint);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.control-hints b { color: var(--parchment-dim); font-weight: 600; letter-spacing: 0.08em; }

.title-scroll { display: flex; flex-direction: column; align-items: flex-end; gap: 30px; padding-bottom: 20px; }

.license-preview {
  position: relative;
  width: min(360px, 100%);
  padding: 18px 20px 16px;
  border: 1px solid rgba(228, 183, 108, 0.42);
  background:
    linear-gradient(140deg, rgba(39, 28, 23, 0.88), rgba(13, 10, 18, 0.92)),
    radial-gradient(circle at 20% 12%, rgba(255, 214, 147, 0.13), transparent 45%);
  box-shadow: 0 26px 60px rgba(0, 0, 0, 0.44), inset 0 0 50px rgba(228, 183, 108, 0.035);
  transform: rotate(-1.2deg);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%);
  overflow: hidden;
}
.license-preview::after {
  content: "";
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(228, 183, 108, 0.18);
  pointer-events: none;
}
.license-topline {
  display: flex;
  justify-content: space-between;
  font-size: 8px;
  letter-spacing: 0.24em;
  color: var(--gold);
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line-soft);
}
.license-body { display: flex; align-items: center; gap: 15px; margin: 17px 0; position: relative; z-index: 1; }
.license-seal {
  width: 58px;
  height: 58px;
  flex: none;
  display: grid;
  place-items: center;
  border: 1px solid var(--gold);
  border-radius: 50%;
  font-family: var(--serif);
  font-size: 27px;
  color: var(--gold-bright);
  box-shadow: inset 0 0 18px rgba(228, 183, 108, 0.11), 0 0 24px rgba(228, 183, 108, 0.08);
}
.license-body h2 { margin: 0; font-family: var(--serif); font-weight: 400; letter-spacing: 0.2em; font-size: 18px; }
.license-body p { margin: 5px 0 0; color: var(--muted); font-size: 9px; line-height: 1.5; letter-spacing: 0.04em; }
.license-stats { display: flex; justify-content: space-between; gap: 8px; border-top: 1px solid var(--line-soft); padding-top: 12px; position: relative; z-index: 1; }
.license-stats span { display: flex; flex-direction: column; color: var(--faint); font-size: 7px; letter-spacing: 0.16em; text-transform: uppercase; }
.license-stats b { color: var(--parchment); font-family: var(--serif); font-size: 18px; font-weight: 400; letter-spacing: 0; }
.license-rune {
  position: absolute;
  right: -10px;
  bottom: 4px;
  font-size: 88px;
  color: rgba(228, 183, 108, 0.055);
  pointer-events: none;
}

.title-aside {
  max-width: 310px;
  text-align: right;
  font-family: var(--serif);
  font-size: 13px;
  font-style: italic;
  line-height: 1.65;
  color: #9c8d81;
}
.title-aside span { display: block; margin-top: 10px; font-family: var(--sans); font-style: normal; font-size: 8px; letter-spacing: 0.22em; text-transform: uppercase; color: var(--faint); }

.title-footer {
  padding-top: 15px;
  border-top: 1px solid var(--line-soft);
  color: var(--faint);
  font-size: 8px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

/* ============================== HUD ============================== */
#hud { position: absolute; inset: 0; z-index: 5; pointer-events: none; padding: calc(16px + var(--safe-top)) 20px calc(14px + var(--safe-bottom)); }
#hud button { pointer-events: auto; }

.hud-top {
  display: grid;
  grid-template-columns: minmax(280px, 1fr) auto minmax(210px, 1fr);
  gap: 20px;
  align-items: start;
}

.hunter-hud {
  display: flex;
  gap: 11px;
  align-items: center;
  width: min(370px, 100%);
  padding: 10px 13px 11px;
  background: linear-gradient(120deg, rgba(11, 8, 17, 0.9), rgba(20, 14, 27, 0.72));
  border-left: 1px solid rgba(228, 183, 108, 0.48);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  backdrop-filter: blur(9px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}

.rank-seal {
  flex: none;
  width: 48px;
  height: 48px;
  border: 1px solid var(--gold);
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-size: 22px;
  color: var(--gold-bright);
  background: radial-gradient(circle, rgba(228, 183, 108, 0.12), transparent 70%);
  box-shadow: inset 0 0 14px rgba(228, 183, 108, 0.09);
}

.hunter-vitals { flex: 1; min-width: 0; }
.hunter-line { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 6px; }
.hunter-name { font-family: var(--serif); font-size: 13px; letter-spacing: 0.14em; text-transform: uppercase; }
.hunter-tag { font-size: 7px; color: var(--faint); letter-spacing: 0.2em; }

.bar { position: relative; height: 13px; margin-bottom: 5px; background: rgba(0, 0, 0, 0.56); overflow: hidden; border: 1px solid rgba(255, 255, 255, 0.05); }
.bar-fill { position: absolute; inset: 0; width: 100%; transform-origin: left center; transition: transform 160ms ease-out; }
.hp-bar .bar-fill { background: linear-gradient(90deg, #9e3947, #df5968 55%, #f58983); box-shadow: 0 0 12px rgba(239, 100, 114, 0.24); }
.aether-bar { height: 7px; }
.aether-bar .bar-fill { background: linear-gradient(90deg, #3e6fa7, #60a9e5 58%, #a9d9ff); box-shadow: 0 0 10px rgba(96, 169, 229, 0.2); }
.bar-text { position: absolute; right: 5px; top: 50%; transform: translateY(-50%); font-family: var(--mono); font-size: 7px; color: rgba(255, 255, 255, 0.7); text-shadow: 0 1px 2px #000; letter-spacing: 0.02em; }
.bar-chips { position: absolute; inset: 0; display: flex; }
.bar-chips i { flex: 1; border-right: 1px solid rgba(0,0,0,0.3); }
.boon-strip { display: flex; gap: 3px; margin-top: 5px; min-height: 12px; flex-wrap: wrap; }
.boon-pip {
  width: 19px;
  height: 15px;
  display: inline-grid;
  place-items: center;
  border: 1px solid rgba(228, 183, 108, 0.22);
  background: rgba(228, 183, 108, 0.08);
  color: var(--gold-bright);
  font-size: 8px;
  position: relative;
}
.boon-pip b { position: absolute; right: -2px; bottom: -3px; font-size: 6px; color: var(--parchment); }

.floor-hud { text-align: center; min-width: 150px; padding-top: 2px; }
.floor-kicker { font-size: 7px; letter-spacing: 0.34em; color: var(--faint); }
.floor-number { font-family: var(--serif); font-size: 21px; letter-spacing: 0.16em; color: var(--parchment); margin-top: 2px; text-shadow: 0 2px 18px rgba(0, 0, 0, 0.8); }
.floor-theme { font-size: 8px; letter-spacing: 0.17em; text-transform: uppercase; color: var(--gold); margin: 2px 0 6px; }
.seal-track { width: 100%; height: 2px; background: rgba(255, 255, 255, 0.09); overflow: hidden; }
.seal-fill { height: 100%; width: 0%; background: linear-gradient(90deg, var(--gold-dark), var(--gold-bright)); transition: width 300ms ease; }
.seal-text { margin-top: 4px; font-size: 6px; letter-spacing: 0.22em; color: var(--faint); }

.hud-right { display: flex; flex-direction: column; align-items: flex-end; gap: 7px; }
.shard-balance { display: flex; align-items: center; gap: 5px; padding: 5px 10px; border: 1px solid var(--line-soft); background: rgba(10, 8, 15, 0.72); backdrop-filter: blur(8px); }
.shard-glyph { color: var(--gold-bright); font-size: 13px; text-shadow: 0 0 12px rgba(255, 219, 153, 0.5); }
.shard-balance #shard-count { font-family: var(--mono); font-size: 12px; color: var(--gold-bright); }
.shard-label { font-size: 6px; letter-spacing: 0.2em; color: var(--faint); margin-left: 2px; }

.map-wrap { position: relative; padding: 5px; border: 1px solid var(--line-soft); background: rgba(8, 6, 13, 0.74); backdrop-filter: blur(8px); }
#minimap { display: block; width: 150px; height: 112px; opacity: 0.9; }
.map-room-name { position: absolute; left: 6px; right: 6px; bottom: 5px; font-size: 6px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--parchment-dim); text-align: center; background: linear-gradient(90deg, transparent, rgba(0, 0, 0, 0.65), transparent); padding: 2px 0; }

.boss-hud {
  position: absolute;
  top: calc(96px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  width: min(620px, 62vw);
  text-align: center;
}
.boss-identity { display: flex; align-items: baseline; justify-content: center; gap: 12px; margin-bottom: 4px; }
.boss-kicker { font-size: 7px; letter-spacing: 0.3em; color: var(--rose); }
.boss-name { font-family: var(--serif); font-size: 17px; letter-spacing: 0.16em; text-transform: uppercase; color: #fff0e6; text-shadow: 0 2px 20px rgba(0, 0, 0, 0.8); }
.boss-bar { position: relative; height: 8px; background: rgba(0, 0, 0, 0.72); border: 1px solid rgba(241, 125, 141, 0.28); overflow: hidden; }
#boss-fill { position: absolute; inset: 0; width: 100%; transform-origin: left; background: linear-gradient(90deg, #7a1b2b, #e34e63 65%, #ff9a8c); box-shadow: 0 0 20px rgba(241, 94, 110, 0.4); }
#boss-delayed { position: absolute; inset: 0; width: 100%; transform-origin: left; background: rgba(255, 225, 184, 0.32); transition: transform 700ms ease 180ms; }
.boss-phase { margin-top: 3px; font-size: 6px; letter-spacing: 0.26em; color: var(--gold); }

.contract-chip {
  position: absolute;
  top: calc(210px + var(--safe-top));
  left: 20px;
  width: 236px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 10px;
  background: rgba(9, 7, 14, 0.68);
  border-left: 1px solid rgba(228, 183, 108, 0.32);
  backdrop-filter: blur(7px);
  opacity: 0.8;
}
.contract-mark { color: var(--gold); font-size: 13px; }
.contract-chip > div { display: flex; flex-direction: column; flex: 1; min-width: 0; }
.contract-label { font-size: 6px; letter-spacing: 0.2em; color: var(--faint); }
.contract-title { color: var(--parchment-dim); font-family: var(--serif); font-size: 11px; letter-spacing: 0.04em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.contract-progress { font-family: var(--mono); font-size: 8px; color: var(--gold); white-space: nowrap; }

.toast-stack { position: absolute; top: calc(105px + var(--safe-top)); right: 20px; display: flex; flex-direction: column; gap: 7px; align-items: flex-end; width: min(320px, 70vw); }
.toast {
  padding: 8px 12px;
  background: linear-gradient(100deg, rgba(15, 11, 21, 0.94), rgba(32, 23, 30, 0.82));
  border-left: 2px solid var(--gold);
  color: var(--parchment-dim);
  font-size: 9px;
  letter-spacing: 0.07em;
  box-shadow: 0 8px 26px rgba(0, 0, 0, 0.3);
  animation: toastIn 260ms ease both, toastOut 350ms ease 2.6s both;
}
.toast b { color: var(--gold-bright); }
.toast.rank { border-left-color: var(--teal); }
.toast.danger { border-left-color: var(--rose); }
@keyframes toastIn { from { opacity: 0; transform: translateX(18px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px); } }

.interact-prompt {
  position: absolute;
  left: 50%;
  bottom: calc(116px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 14px;
  background: rgba(8, 6, 13, 0.84);
  border: 1px solid var(--line);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--parchment);
  backdrop-filter: blur(8px);
  animation: promptPulse 1.6s ease-in-out infinite;
}
.keycap { display: grid; place-items: center; min-width: 22px; height: 22px; border: 1px solid var(--gold); color: var(--gold-bright); font-family: var(--mono); font-size: 10px; }
@keyframes promptPulse { 0%,100% { box-shadow: 0 0 0 rgba(228,183,108,0); } 50% { box-shadow: 0 0 24px rgba(228,183,108,0.12); } }

.ability-bar {
  position: absolute;
  left: 50%;
  bottom: calc(20px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: stretch;
  gap: 5px;
  padding: 5px;
  background: rgba(8, 6, 13, 0.62);
  border: 1px solid rgba(228, 183, 108, 0.12);
  backdrop-filter: blur(10px);
}
.ability {
  position: relative;
  width: 66px;
  height: 48px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  background: linear-gradient(160deg, rgba(35, 26, 40, 0.72), rgba(10, 8, 15, 0.8));
  border: 1px solid rgba(255, 255, 255, 0.06);
  overflow: hidden;
}
.ability-icon { font-size: 15px; color: var(--gold-bright); }
.ability-name { font-size: 6px; letter-spacing: 0.18em; color: var(--parchment-dim); }
.ability-key { position: absolute; top: 2px; right: 4px; font-family: var(--mono); font-size: 5px; color: var(--faint); }
.cooldown-mask { position: absolute; inset: 0; background: rgba(4, 3, 8, 0.74); transform-origin: bottom; transform: scaleY(0); pointer-events: none; }
.ability.flash { animation: abilityFlash 260ms ease; }
@keyframes abilityFlash { 0% { border-color: var(--gold); box-shadow: inset 0 0 20px rgba(228,183,108,0.3); } 100% { border-color: rgba(255,255,255,0.06); } }

.pause-button { position: absolute; top: calc(18px + var(--safe-top)); right: 20px; z-index: 9; width: 34px; height: 34px; font-size: 11px; }
#hud .pause-button { display: none; }

.touch-controls { display: none; }

/* ============================== HUB ============================== */
.hub-screen {
  background:
    radial-gradient(ellipse at 30% 15%, rgba(65, 39, 64, 0.27), transparent 48%),
    linear-gradient(115deg, rgba(5, 4, 9, 0.92), rgba(7, 5, 12, 0.72) 55%, rgba(5, 4, 9, 0.9));
  padding: calc(18px + var(--safe-top)) clamp(14px, 3vw, 42px) calc(16px + var(--safe-bottom));
}

.hub-shell {
  width: min(1360px, 100%);
  height: 100%;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.hub-header { display: flex; align-items: center; justify-content: space-between; gap: 18px; flex: none; padding-bottom: 13px; border-bottom: 1px solid var(--line-soft); }
.hub-brand { display: flex; align-items: center; gap: 13px; }
.brand-glyph { font-size: 26px; color: var(--gold); text-shadow: 0 0 22px rgba(228, 183, 108, 0.3); }
.hub-brand h2 { margin: 0; font-family: var(--serif); font-weight: 400; font-size: clamp(16px, 1.8vw, 22px); letter-spacing: 0.18em; }
.hub-brand p { margin: 3px 0 0; font-size: 8px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--faint); }
.hub-currency { display: flex; align-items: baseline; gap: 8px; margin-left: auto; color: var(--gold-bright); }
.hub-currency span { font-size: 17px; }
.hub-currency b { font-family: var(--mono); font-size: 19px; font-weight: 400; }
.hub-currency em { font-size: 7px; font-style: normal; letter-spacing: 0.2em; color: var(--faint); }

.hub-layout {
  display: grid;
  grid-template-columns: 280px 150px minmax(0, 1fr);
  gap: clamp(14px, 2vw, 26px);
  min-height: 0;
  flex: 1;
}

.hunter-card {
  align-self: start;
  border: 1px solid var(--line-soft);
  background: linear-gradient(170deg, rgba(27, 19, 32, 0.88), rgba(9, 7, 14, 0.92));
  box-shadow: 0 20px 44px rgba(0, 0, 0, 0.24);
  overflow: hidden;
}

.hunter-portrait {
  position: relative;
  height: 190px;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 32%, rgba(196, 160, 219, 0.18), transparent 33%),
    linear-gradient(180deg, #1c1729, #0c0a14);
  border-bottom: 1px solid var(--line-soft);
}
.portrait-moon {
  position: absolute;
  width: 112px;
  height: 112px;
  border-radius: 50%;
  left: 50%;
  top: 26px;
  transform: translateX(-50%);
  background: radial-gradient(circle at 42% 38%, #f8eac9, #b68f6d 55%, #4e3444 100%);
  box-shadow: 0 0 46px rgba(228, 183, 108, 0.18);
  opacity: 0.55;
}
.portrait-silhouette { position: absolute; left: 50%; bottom: -14px; width: 170px; height: 170px; transform: translateX(-50%); }
.portrait-silhouette i {
  position: absolute;
  width: 42px;
  height: 44px;
  border-radius: 48% 48% 42% 42%;
  left: 64px;
  top: 26px;
  background: #0a0810;
  box-shadow: 0 0 0 1px rgba(228, 183, 108, 0.25), 0 0 26px rgba(0,0,0,0.9);
}
.portrait-silhouette b {
  position: absolute;
  left: 30px;
  top: 65px;
  width: 112px;
  height: 112px;
  background: linear-gradient(155deg, #241c32, #09070e 70%);
  clip-path: polygon(37% 0, 63% 0, 100% 54%, 82% 100%, 18% 100%, 0 54%);
  box-shadow: inset 0 0 20px rgba(255, 255, 255, 0.04);
}
.portrait-silhouette span {
  position: absolute;
  width: 2px;
  height: 122px;
  right: 21px;
  top: 38px;
  transform: rotate(-21deg);
  background: linear-gradient(to bottom, transparent, #d8c195 30%, #f6e4b6 60%, transparent);
  box-shadow: 0 0 9px rgba(255, 232, 180, 0.5);
}
.portrait-silhouette::after {
  content: "";
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  height: 24px;
  background: radial-gradient(ellipse, rgba(228,183,108,0.18), transparent 70%);
}
.portrait-rank {
  position: absolute;
  right: 12px;
  top: 12px;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--gold);
  border-radius: 50%;
  color: var(--gold-bright);
  font-family: var(--serif);
  font-size: 18px;
  background: rgba(8, 6, 12, 0.68);
}

.hunter-card-body { padding: 16px; }
.card-kicker { font-size: 7px; letter-spacing: 0.24em; color: var(--gold); text-transform: uppercase; }
.hunter-card-body h3 { margin: 5px 0 2px; font-family: var(--serif); font-weight: 400; font-size: 23px; letter-spacing: 0.08em; }
.hunter-card-body > p { margin: 0 0 14px; font-size: 9px; letter-spacing: 0.06em; color: var(--muted); }
.xp-line { height: 3px; background: rgba(255,255,255,0.08); overflow: hidden; }
.xp-line div { height: 100%; width: 0%; background: linear-gradient(90deg, var(--gold-dark), var(--gold-bright)); transition: width 400ms; }
.xp-labels { display: flex; justify-content: space-between; margin-top: 5px; font-size: 7px; letter-spacing: 0.08em; color: var(--faint); }
.xp-labels span:last-child { color: var(--gold); }
.hunter-mini-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin-top: 15px; padding-top: 13px; border-top: 1px solid var(--line-soft); }
.hunter-mini-stats span { display: flex; flex-direction: column; font-size: 6px; line-height: 1.5; letter-spacing: 0.13em; color: var(--faint); }
.hunter-mini-stats b { font-family: var(--serif); font-size: 17px; font-weight: 400; color: var(--parchment); letter-spacing: 0; }

.hub-nav { display: flex; flex-direction: column; gap: 2px; align-self: start; border-left: 1px solid var(--line-soft); padding-left: 10px; }
.hub-nav button {
  text-align: left;
  padding: 13px 14px;
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  border-left: 1px solid transparent;
  transition: color 160ms, background 160ms, border 160ms;
  white-space: nowrap;
}
.hub-nav button:hover { color: var(--parchment); background: rgba(228, 183, 108, 0.04); }
.hub-nav button.active { color: var(--gold-bright); border-left-color: var(--gold); background: linear-gradient(90deg, rgba(228,183,108,0.08), transparent); }

.hub-main {
  min-height: 0;
  overflow-y: auto;
  padding: 0 8px 30px 0;
  scrollbar-width: thin;
  scrollbar-color: rgba(228,183,108,0.26) transparent;
}
.hub-main::-webkit-scrollbar { width: 5px; }
.hub-main::-webkit-scrollbar-thumb { background: rgba(228,183,108,0.26); }

.hub-panel { animation: panelIn 320ms ease both; }
@keyframes panelIn { from { opacity: 0; transform: translateY(7px); } to { opacity: 1; transform: none; } }

.panel-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; padding-bottom: 12px; margin-bottom: 18px; border-bottom: 1px solid var(--line-soft); }
.panel-head h2 { margin: 0; font-family: var(--serif); font-weight: 400; font-size: clamp(24px, 3vw, 38px); letter-spacing: 0.05em; }
.panel-head p { margin: 5px 0 0; color: var(--muted); font-size: 10px; letter-spacing: 0.04em; }
.panel-head .head-mark { font-family: var(--serif); font-size: 30px; color: rgba(228,183,108,0.23); }

.descent-hero {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 230px;
  gap: 24px;
  padding: clamp(20px, 3vw, 32px);
  border: 1px solid var(--line-soft);
  background:
    radial-gradient(ellipse at 76% 20%, rgba(228, 183, 108, 0.09), transparent 42%),
    linear-gradient(135deg, rgba(31, 21, 36, 0.9), rgba(8, 6, 13, 0.92));
  overflow: hidden;
}
.descent-hero::before {
  content: "✦";
  position: absolute;
  right: 100px;
  bottom: -65px;
  font-size: 240px;
  color: rgba(228, 183, 108, 0.035);
  pointer-events: none;
}
.descent-hero h3 { margin: 6px 0 10px; font-family: var(--serif); font-weight: 400; font-size: clamp(23px, 2.5vw, 32px); }
.descent-hero p { margin: 0 0 18px; color: var(--muted); font-size: 11px; line-height: 1.75; max-width: 560px; }
.checkpoint-row { display: flex; gap: 8px; flex-wrap: wrap; margin: 16px 0 22px; }
.checkpoint-pill { padding: 7px 12px; border: 1px solid var(--line-soft); color: var(--faint); font-size: 8px; letter-spacing: 0.14em; text-transform: uppercase; }
.checkpoint-pill.unlocked { color: var(--gold); border-color: rgba(228, 183, 108, 0.3); background: rgba(228, 183, 108, 0.05); }
.checkpoint-pill.current { color: var(--ink); background: var(--gold); border-color: var(--gold); }
.descent-actions { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.descent-actions .primary-button { min-height: 48px; }
.run-note { font-size: 8px; color: var(--faint); letter-spacing: 0.08em; }
.descent-side { position: relative; z-index: 1; display: flex; flex-direction: column; gap: 8px; }
.stat-card { padding: 11px 13px; background: rgba(0,0,0,0.22); border: 1px solid var(--line-soft); }
.stat-card span { display: block; font-size: 6px; letter-spacing: 0.18em; color: var(--faint); text-transform: uppercase; }
.stat-card b { font-family: var(--serif); font-weight: 400; font-size: 21px; color: var(--parchment); }
.stat-card em { font-style: normal; font-size: 7px; color: var(--gold); margin-left: 4px; }

.section-label { margin: 22px 0 10px; font-size: 8px; letter-spacing: 0.26em; color: var(--gold); text-transform: uppercase; }
.loadout-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.loadout-chip { padding: 11px 12px; background: rgba(255,255,255,0.018); border: 1px solid var(--line-soft); min-width: 0; }
.loadout-chip span { font-size: 6px; letter-spacing: 0.18em; color: var(--faint); text-transform: uppercase; }
.loadout-chip b { display: block; margin-top: 3px; font-family: var(--serif); font-weight: 400; font-size: 13px; color: var(--parchment-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.loadout-chip em { font-style: normal; color: var(--gold); font-size: 9px; }

.lore-strip { margin-top: 22px; padding: 14px 17px; border-left: 1px solid rgba(228,183,108,0.36); background: linear-gradient(90deg, rgba(228,183,108,0.04), transparent); color: var(--muted); font-family: var(--serif); font-size: 12px; font-style: italic; line-height: 1.7; }

.license-panel-grid { display: grid; grid-template-columns: minmax(250px, 0.82fr) minmax(0, 1.18fr); gap: 22px; }
.big-license {
  position: relative;
  padding: 24px;
  border: 1px solid rgba(228,183,108,0.34);
  background:
    radial-gradient(circle at 83% 11%, rgba(255, 219, 153, 0.11), transparent 33%),
    linear-gradient(145deg, #241b1c, #0d0a12 70%);
  box-shadow: 0 24px 50px rgba(0,0,0,0.22);
  overflow: hidden;
}
.big-license::before { content: ""; position: absolute; inset: 8px; border: 1px solid rgba(228,183,108,0.15); pointer-events: none; }
.big-license .license-header { display: flex; justify-content: space-between; font-size: 7px; letter-spacing: 0.2em; color: var(--gold); border-bottom: 1px solid var(--line-soft); padding-bottom: 11px; }
.big-license-rank { display: flex; align-items: center; gap: 20px; margin: 24px 0 18px; }
.big-rank-seal { width: 92px; height: 92px; flex: none; display: grid; place-items: center; border: 1px solid var(--gold); border-radius: 50%; font-family: var(--serif); font-size: 48px; color: var(--gold-bright); box-shadow: inset 0 0 26px rgba(228,183,108,0.12), 0 0 34px rgba(228,183,108,0.08); }
.big-license-rank h3 { margin: 0; font-family: var(--serif); font-weight: 400; font-size: 28px; letter-spacing: 0.08em; }
.big-license-rank p { margin: 5px 0 0; font-size: 9px; color: var(--muted); }
.big-license .xp-line { height: 4px; }
.license-perk { margin-top: 18px; padding: 12px; background: rgba(0,0,0,0.22); border-left: 1px solid var(--gold-dark); color: var(--parchment-dim); font-size: 10px; line-height: 1.6; }
.license-rune-bg { position: absolute; right: -30px; bottom: -40px; font-size: 180px; color: rgba(228,183,108,0.04); }

.rank-ladder { display: flex; flex-direction: column; gap: 7px; }
.rank-step { display: flex; align-items: center; gap: 12px; padding: 11px 13px; border: 1px solid var(--line-soft); background: rgba(255,255,255,0.015); }
.rank-step.current { border-color: rgba(228,183,108,0.4); background: rgba(228,183,108,0.05); }
.rank-step.locked { opacity: 0.5; }
.rank-dot { width: 30px; height: 30px; flex: none; display: grid; place-items: center; border: 1px solid var(--line); border-radius: 50%; font-family: var(--serif); color: var(--gold); font-size: 14px; }
.rank-step.current .rank-dot { background: var(--gold); color: var(--ink); }
.rank-step div { flex: 1; min-width: 0; }
.rank-step h4 { margin: 0; font-size: 9px; letter-spacing: 0.1em; color: var(--parchment-dim); font-weight: 600; }
.rank-step p { margin: 3px 0 0; font-size: 8px; color: var(--faint); }
.rank-xp { font-family: var(--mono); font-size: 8px; color: var(--gold); }
.license-stats-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin-top: 17px; }
.mini-stat { padding: 10px 12px; border: 1px solid var(--line-soft); }
.mini-stat span { display: block; font-size: 6px; letter-spacing: 0.16em; color: var(--faint); text-transform: uppercase; }
.mini-stat b { font-family: var(--serif); font-weight: 400; font-size: 19px; }

.forge-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 12px; }
.forge-card { position: relative; display: flex; flex-direction: column; gap: 10px; padding: 15px; border: 1px solid var(--line-soft); background: linear-gradient(155deg, rgba(255,255,255,0.022), rgba(0,0,0,0.12)); min-height: 186px; }
.forge-card.equipped { border-color: rgba(228,183,108,0.45); background: linear-gradient(155deg, rgba(228,183,108,0.07), rgba(0,0,0,0.15)); }
.forge-card.locked { opacity: 0.66; }
.forge-card-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.forge-icon { width: 38px; height: 38px; display: grid; place-items: center; border: 1px solid var(--line); color: var(--gold-bright); font-size: 18px; background: radial-gradient(circle, rgba(228,183,108,0.12), transparent 70%); }
.forge-level { font-family: var(--mono); font-size: 8px; color: var(--gold); letter-spacing: 0.08em; }
.forge-card h4 { margin: 0; font-family: var(--serif); font-weight: 400; font-size: 17px; letter-spacing: 0.04em; }
.forge-card p { margin: 0; font-size: 9px; line-height: 1.6; color: var(--muted); flex: 1; }
.forge-stats { display: flex; flex-wrap: wrap; gap: 4px 9px; font-size: 7px; color: var(--faint); letter-spacing: 0.05em; }
.forge-stats b { color: var(--parchment-dim); font-weight: 600; }
.forge-actions { display: flex; gap: 5px; flex-wrap: wrap; }
.tiny-button { padding: 7px 10px; border: 1px solid var(--line-soft); color: var(--parchment-dim); font-size: 7px; letter-spacing: 0.16em; text-transform: uppercase; transition: 150ms; }
.tiny-button:hover { border-color: var(--gold); color: var(--gold-bright); background: rgba(228,183,108,0.06); }
.tiny-button:disabled { opacity: 0.35; cursor: default; }
.tiny-button.primary { background: var(--gold); border-color: var(--gold); color: var(--ink); }
.tiny-button.primary:hover { background: var(--gold-bright); color: var(--ink); }

.contract-list { display: grid; gap: 10px; }
.contract-card { display: grid; grid-template-columns: 46px minmax(0, 1fr) auto; gap: 14px; align-items: center; padding: 15px; border: 1px solid var(--line-soft); background: linear-gradient(100deg, rgba(255,255,255,0.02), rgba(0,0,0,0.08)); }
.contract-card.complete { border-color: rgba(120,227,199,0.36); background: linear-gradient(100deg, rgba(120,227,199,0.055), rgba(0,0,0,0.08)); }
.contract-icon { width: 42px; height: 42px; display: grid; place-items: center; border: 1px solid var(--line); border-radius: 50%; color: var(--gold); font-size: 18px; }
.contract-card h4 { margin: 0 0 4px; font-family: var(--serif); font-weight: 400; font-size: 16px; }
.contract-card p { margin: 0; font-size: 8px; color: var(--muted); }
.contract-bar { height: 3px; margin-top: 9px; background: rgba(255,255,255,0.08); overflow: hidden; }
.contract-bar div { height: 100%; background: linear-gradient(90deg, var(--gold-dark), var(--gold-bright)); }
.contract-bar.complete div { background: linear-gradient(90deg, #3a8c7b, var(--teal)); }
.contract-reward { text-align: right; display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.contract-reward span { font-size: 7px; color: var(--faint); letter-spacing: 0.1em; }
.contract-reward b { font-family: var(--mono); font-weight: 400; font-size: 10px; color: var(--gold); }
.contract-reward .tiny-button { margin-top: 4px; }
.contract-empty { padding: 30px; text-align: center; border: 1px dashed var(--line); color: var(--muted); font-size: 10px; }

.codex-tabs { display: flex; gap: 3px; flex-wrap: wrap; margin-bottom: 15px; }
.codex-tabs button { padding: 8px 13px; border: 1px solid var(--line-soft); color: var(--muted); font-size: 8px; letter-spacing: 0.16em; text-transform: uppercase; }
.codex-tabs button.active { color: var(--ink); background: var(--gold); border-color: var(--gold); }
.codex-grid { display: grid; gap: 10px; }
.codex-entry { padding: 15px 17px; border-left: 1px solid rgba(228,183,108,0.3); background: linear-gradient(90deg, rgba(228,183,108,0.035), transparent); }
.codex-entry h3 { margin: 0 0 6px; font-family: var(--serif); font-weight: 400; font-size: 17px; color: var(--parchment); }
.codex-entry p { margin: 0; color: var(--muted); font-size: 10px; line-height: 1.75; }
.bestiary-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 9px; }
.bestiary-card { padding: 13px; border: 1px solid var(--line-soft); background: rgba(255,255,255,0.018); }
.bestiary-top { display: flex; align-items: center; gap: 9px; margin-bottom: 7px; }
.bestiary-icon { width: 30px; height: 30px; display: grid; place-items: center; border: 1px solid var(--line); color: var(--gold); }
.bestiary-top h4 { margin: 0; font-family: var(--serif); font-weight: 400; font-size: 15px; }
.bestiary-top span { display: block; font-size: 6px; letter-spacing: 0.12em; color: var(--faint); text-transform: uppercase; }
.bestiary-card p { margin: 0 0 7px; font-size: 9px; line-height: 1.6; color: var(--muted); }
.bestiary-tell { border-top: 1px solid var(--line-soft); padding-top: 6px; font-size: 8px; line-height: 1.55; color: var(--gold); }

/* ============================== OVERLAYS ============================== */
.overlay-screen {
  z-index: 20;
  align-items: center;
  justify-content: center;
  padding: calc(20px + var(--safe-top)) 18px calc(20px + var(--safe-bottom));
  background: radial-gradient(ellipse at 50% 44%, rgba(19, 12, 27, 0.72), rgba(4, 3, 8, 0.94));
  backdrop-filter: blur(7px);
}

.boon-shell { width: min(1000px, 100%); text-align: center; }
.boon-shell h2 { margin: 7px 0 5px; font-family: var(--serif); font-weight: 400; font-size: clamp(28px, 4vw, 46px); letter-spacing: 0.05em; }
.boon-sub { margin: 0; color: var(--muted); font-size: 10px; letter-spacing: 0.04em; }
.boon-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: clamp(10px, 1.6vw, 20px); margin: clamp(22px, 4vh, 42px) 0 18px; }
.boon-card {
  position: relative;
  min-height: 300px;
  padding: 24px 20px 20px;
  text-align: left;
  border: 1px solid rgba(228,183,108,0.22);
  background:
    radial-gradient(circle at 50% 0%, rgba(228,183,108,0.09), transparent 45%),
    linear-gradient(170deg, rgba(34, 24, 38, 0.96), rgba(8, 6, 13, 0.97));
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
  transition: transform 200ms, border-color 200ms, box-shadow 200ms;
  overflow: hidden;
  animation: cardIn 420ms cubic-bezier(.2,.8,.2,1) both;
}
.boon-card:nth-child(2) { animation-delay: 70ms; }
.boon-card:nth-child(3) { animation-delay: 140ms; }
.boon-card:hover { transform: translateY(-7px); border-color: var(--gold); box-shadow: 0 18px 50px rgba(0,0,0,0.4), 0 0 30px rgba(228,183,108,0.08); }
@keyframes cardIn { from { opacity: 0; transform: translateY(20px) scale(0.98); } to { opacity: 1; transform: none; } }
.boon-card::after { content: ""; position: absolute; inset: 7px; border: 1px solid rgba(228,183,108,0.08); pointer-events: none; }
.boon-number { position: absolute; right: 14px; top: 9px; font-family: var(--serif); font-size: 40px; color: rgba(228,183,108,0.09); }
.boon-icon { width: 58px; height: 58px; display: grid; place-items: center; border: 1px solid rgba(228,183,108,0.4); border-radius: 50%; font-size: 25px; color: var(--gold-bright); margin-bottom: 21px; box-shadow: inset 0 0 22px rgba(228,183,108,0.09); }
.boon-card h3 { margin: 0 0 5px; font-family: var(--serif); font-weight: 400; font-size: clamp(20px, 2vw, 26px); }
.boon-stack { font-size: 7px; letter-spacing: 0.18em; color: var(--gold); text-transform: uppercase; }
.boon-desc { margin: 16px 0 0; color: var(--parchment-dim); font-size: 11px; line-height: 1.65; }
.boon-flavor { position: absolute; left: 20px; right: 20px; bottom: 20px; margin: 0; color: var(--faint); font-family: var(--serif); font-size: 10px; font-style: italic; line-height: 1.5; }
.boon-card:hover .boon-icon { border-color: var(--gold-bright); box-shadow: 0 0 24px rgba(228,183,108,0.18), inset 0 0 22px rgba(228,183,108,0.14); }
.boon-foot { font-size: 7px; letter-spacing: 0.28em; color: var(--faint); text-transform: uppercase; }
.boon-foot span { color: var(--gold); }

.pause-shell, .result-shell {
  width: min(620px, 100%);
  padding: clamp(22px, 3vw, 36px);
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 50% 0%, rgba(228,183,108,0.07), transparent 43%),
    linear-gradient(170deg, rgba(26, 18, 32, 0.97), rgba(7, 5, 11, 0.98));
  box-shadow: 0 30px 80px rgba(0,0,0,0.5);
  clip-path: polygon(16px 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%, 0 16px);
}
.pause-shell h2, .result-shell h2 { margin: 8px 0 4px; font-family: var(--serif); font-weight: 400; font-size: clamp(28px, 4vw, 42px); letter-spacing: 0.04em; }
.pause-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 21px 0; }
.pause-stats div { padding: 10px; border: 1px solid var(--line-soft); }
.pause-stats span { display: block; font-size: 6px; letter-spacing: 0.16em; color: var(--faint); text-transform: uppercase; }
.pause-stats b { font-family: var(--serif); font-size: 19px; font-weight: 400; }
.pause-settings { display: flex; flex-direction: column; border-top: 1px solid var(--line-soft); border-bottom: 1px solid var(--line-soft); }
.setting-row { display: flex; justify-content: space-between; align-items: center; padding: 12px 4px; border-bottom: 1px solid rgba(255,255,255,0.035); font-size: 10px; color: var(--muted); letter-spacing: 0.05em; text-align: left; }
.setting-row:last-child { border-bottom: 0; }
.setting-row b { font-family: var(--mono); font-size: 8px; color: var(--gold); letter-spacing: 0.12em; }
.pause-actions, .result-actions { display: flex; gap: 10px; margin-top: 22px; flex-wrap: wrap; }
.pause-actions button, .result-actions button { flex: 1; min-width: 140px; }
.pause-note { margin: 15px 0 0; font-size: 8px; line-height: 1.6; color: var(--faint); }

.result-shell { width: min(700px, 100%); }
.result-sub { margin: 4px 0 20px; font-family: var(--serif); font-size: 13px; font-style: italic; color: var(--muted); }
.result-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.result-grid div { padding: 12px 10px; border: 1px solid var(--line-soft); text-align: center; }
.result-grid span { display: block; font-size: 6px; letter-spacing: 0.16em; color: var(--faint); text-transform: uppercase; }
.result-grid b { display: block; margin-top: 3px; font-family: var(--serif); font-weight: 400; font-size: 22px; color: var(--parchment); }
.result-grid b.gold { color: var(--gold-bright); }
.result-columns { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 18px; }
.result-column { padding: 13px; border: 1px solid var(--line-soft); }
.result-column h4 { margin: 0 0 8px; font-size: 7px; letter-spacing: 0.2em; color: var(--gold); text-transform: uppercase; }
.result-column p { margin: 0 0 5px; font-size: 9px; line-height: 1.55; color: var(--muted); display: flex; justify-content: space-between; gap: 10px; }
.result-column p b { color: var(--parchment-dim); font-weight: 500; }
.result-column .empty { color: var(--faint); font-style: italic; }

.tutorial-card {
  position: absolute;
  z-index: 8;
  left: 50%;
  bottom: calc(90px + var(--safe-bottom));
  transform: translateX(-50%);
  width: min(600px, calc(100% - 32px));
  padding: 14px 17px;
  background: rgba(10, 8, 16, 0.94);
  border: 1px solid var(--line);
  backdrop-filter: blur(12px);
  box-shadow: 0 20px 50px rgba(0,0,0,0.42);
  animation: screenIn 400ms ease both;
}
.tutorial-top { display: flex; justify-content: space-between; align-items: center; font-size: 7px; letter-spacing: 0.22em; color: var(--gold); }
.tutorial-top button { color: var(--muted); font-size: 17px; line-height: 1; padding: 0 3px; }
.tutorial-card h3 { margin: 5px 0 10px; font-family: var(--serif); font-weight: 400; font-size: 19px; }
.tutorial-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px 12px; }
.tutorial-grid div { display: flex; flex-direction: column; gap: 2px; }
.tutorial-grid b { font-family: var(--mono); font-size: 7px; color: var(--gold); letter-spacing: 0.08em; }
.tutorial-grid span { font-size: 8px; line-height: 1.45; color: var(--muted); }

/* ============================== TOUCH ============================== */
body.touch .touch-controls { display: block; }
body.touch .ability-bar { display: none; }
body.touch #hud .pause-button { display: grid; }
body.touch .control-hints { display: none; }
body.touch .interact-prompt { bottom: calc(188px + var(--safe-bottom)); }

.touch-controls { position: absolute; inset: 0; pointer-events: none; }
.joystick-zone {
  position: absolute;
  left: max(20px, env(safe-area-inset-left));
  bottom: calc(22px + var(--safe-bottom));
  width: 132px;
  height: 132px;
  pointer-events: auto;
  touch-action: none;
  display: grid;
  place-items: center;
}
.joystick-ring {
  width: 116px;
  height: 116px;
  border-radius: 50%;
  border: 1px solid rgba(228,183,108,0.24);
  background: radial-gradient(circle, rgba(228,183,108,0.055), rgba(6,4,10,0.35) 68%);
  display: grid;
  place-items: center;
  box-shadow: inset 0 0 28px rgba(0,0,0,0.3);
}
.joystick-knob {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 1px solid rgba(228,183,108,0.55);
  background: radial-gradient(circle at 40% 35%, rgba(255,226,173,0.25), rgba(22,15,24,0.94));
  box-shadow: 0 6px 20px rgba(0,0,0,0.35), inset 0 0 14px rgba(228,183,108,0.12);
  transform: translate(0, 0);
}
.joystick-hint { position: absolute; bottom: -3px; font-size: 6px; letter-spacing: 0.24em; color: var(--faint); }

.touch-buttons {
  position: absolute;
  right: max(18px, env(safe-area-inset-right));
  bottom: calc(18px + var(--safe-bottom));
  width: 196px;
  height: 196px;
  pointer-events: none;
}
.touch-btn {
  position: absolute;
  width: 62px;
  height: 62px;
  border-radius: 50%;
  border: 1px solid rgba(228,183,108,0.38);
  background: radial-gradient(circle at 40% 35%, rgba(255,226,173,0.13), rgba(10,7,14,0.86));
  color: var(--gold-bright);
  font-size: 20px;
  display: grid;
  place-items: center;
  pointer-events: auto;
  touch-action: none;
  box-shadow: 0 7px 20px rgba(0,0,0,0.3), inset 0 0 16px rgba(228,183,108,0.06);
  transition: transform 80ms, background 80ms;
  user-select: none;
  -webkit-user-select: none;
}
.touch-btn:active, .touch-btn.pressed { transform: scale(0.91); background: radial-gradient(circle, rgba(228,183,108,0.3), rgba(10,7,14,0.9)); }
.touch-btn.cooling { opacity: 0.38; }
.touch-btn.cooling::after { content: ""; position: absolute; inset: 5px; border: 1px solid rgba(255,255,255,0.13); border-radius: 50%; }
.touch-attack { width: 82px; height: 82px; right: 8px; bottom: 2px; font-size: 27px; border-color: rgba(255,219,153,0.55); }
.touch-dash { width: 58px; height: 58px; right: 96px; bottom: 44px; }
.touch-lance { width: 52px; height: 52px; right: 23px; bottom: 96px; }
.touch-nova { width: 52px; height: 52px; right: 96px; bottom: 111px; }
.touch-interact { width: 42px; height: 42px; right: 13px; bottom: 157px; font-size: 15px; }

/* ============================== RESPONSIVE ============================== */
@media (max-width: 1050px) {
  .title-layout { grid-template-columns: minmax(0, 1.3fr) minmax(250px, 0.7fr); gap: 30px; }
  .hub-layout { grid-template-columns: 235px 128px minmax(0, 1fr); }
  .hunter-portrait { height: 165px; }
  .descent-hero { grid-template-columns: 1fr; }
  .descent-side { display: grid; grid-template-columns: repeat(3, 1fr); }
  .license-panel-grid { grid-template-columns: 1fr; }
}

@media (max-width: 800px) {
  .title-screen { padding-left: 24px; padding-right: 24px; }
  .title-layout { grid-template-columns: 1fr; align-items: center; padding-top: 30px; }
  .title-scroll { display: none; }
  .title-copy { max-width: 100%; }
  .game-title { white-space: normal; font-size: clamp(3.4rem, 15vw, 6rem); line-height: 0.9; }
  .title-rule em { font-size: 10px; letter-spacing: 0.3em; }
  .title-blurb { font-size: 14px; max-width: 480px; }
