function updatePlayer(dt) {
  const p = game.player;
  if (!p) return;
  p.attackCooldown = Math.max(0, p.attackCooldown - dt);
  p.comboTimer = Math.max(0, p.comboTimer - dt);
  p.dashCooldown = Math.max(0, p.dashCooldown - dt);
  p.lanceCooldown = Math.max(0, p.lanceCooldown - dt);
  p.novaCooldown = Math.max(0, p.novaCooldown - dt);
  p.invuln = Math.max(0, p.invuln - dt);
  p.hitFlash = Math.max(0, p.hitFlash - dt);
  p.attackAnim = Math.max(0, p.attackAnim - dt);
  p.doorCooldown = Math.max(0, p.doorCooldown - dt);
  if (!p.alive) return;

  const mv = moveVector();
  if (!isTouchLike() && game.mode === 'playing') {
    const world = screenToWorld(game.mouse.x, game.mouse.y);
    if (Math.hypot(world.x - p.x, world.y - p.y) > 18) p.facing = Math.atan2(world.y - p.y, world.x - p.x);
  } else if (isTouchLike()) {
    const target = nearestEnemy(560);
    if (target) p.facing = angleTo(p, target);
    else if (mv.x || mv.y) p.facing = Math.atan2(mv.y, mv.x);
  }

  if (p.dashTime > 0) {
    p.dashTime -= dt;
    const dashSpeed = 960;
    moveEntity(p, Math.cos(p.dashDir) * dashSpeed * dt, Math.sin(p.dashDir) * dashSpeed * dt);
    p.dashTrail.push({ x: p.x, y: p.y, life: 0.26 });
    if (Math.random() < 0.55) trailParticle(p.x, p.y, '#c9e6ff', 0.24, 2.5);
  } else if (mv.x || mv.y) {
    const s = game.run.stats;
    moveEntity(p, mv.x * s.speed * dt, mv.y * s.speed * dt);
  }
  for (const t of p.dashTrail) t.life -= dt;
  p.dashTrail = p.dashTrail.filter(t => t.life > 0);

  p.aether = Math.min(p.maxAether, p.aether + game.run.stats.regen * dt);

  if (game.mouse.down || game.touch.attack) tryAttack();
  if (p.doorCooldown <= 0) tryDoorTransition(mv);
}

function tryDoorTransition(mv) {
  const room = game.room;
  if (!room || !game.run.sealBroken && !room.cleared) return;
  if (!room.cleared) return;
  const p = game.player;
  for (const [dir, neighborKey] of Object.entries(room.doors)) {
    if (!neighborKey) continue;
    const point = doorPoint(room, dir);
    const inward = dir === 'n' ? { x: 0, y: 1 } : dir === 's' ? { x: 0, y: -1 } : dir === 'w' ? { x: 1, y: 0 } : { x: -1, y: 0 };
    const edge = { x: point.x + inward.x * 42, y: point.y + inward.y * 42 };
    if (Math.hypot(p.x - edge.x, p.y - edge.y) > 42) continue;
    const movingToward = dir === 'n' ? mv.y < -0.15 : dir === 's' ? mv.y > 0.15 : dir === 'w' ? mv.x < -0.15 : mv.x > 0.15;
    if (!movingToward && p.doorCooldown > 0) continue;
    if (!movingToward) continue;
    const next = game.floorData.rooms[neighborKey];
    if (!next) continue;
    enterRoom(neighborKey, DIRS[dir].opposite, false);
    game.fade = 0.85;
    game.audio.play('dash');
    return;
  }
}

